/* -------- Option parsing -------- */

static long parse_num(const char *s, const char *what) {
    char *e;
    errno = 0;
    long v = strtol(s, &e, 10);
    if (errno || e == s || *e) {
        pigz_die("invalid numeric parameter: %s", s);
    }
    (void)what;
    return v;
}

/* A simple argv buffer used to splice env vars / expand options. */
typedef struct {
    char **v;
    int n;
    int cap;
} argv_t;

static void argv_init(argv_t *a) {
    a->v = NULL; a->n = 0; a->cap = 0;
}

static void argv_push(argv_t *a, char *s) {
    if (a->n + 1 >= a->cap) {
        a->cap = a->cap ? a->cap * 2 : 16;
        a->v = (char**)realloc(a->v, a->cap * sizeof(char*));
        if (!a->v) pigz_die("not enough memory");
    }
    a->v[a->n++] = s;
}

static void argv_split(argv_t *a, const char *env) {
    /* split on whitespace, no quoting */
    const char *p = env;
    while (*p) {
        while (*p == ' ' || *p == '\t') p++;
        if (!*p) break;
        const char *b = p;
        while (*p && *p != ' ' && *p != '\t') p++;
        size_t len = (size_t)(p - b);
        char *s = (char*)malloc(len + 1);
        if (!s) pigz_die("not enough memory");
        memcpy(s, b, len);
        s[len] = 0;
        argv_push(a, s);
    }
}

/* Long option struct */
struct longopt {
    const char *name;
