/* Compute XFL byte for gzip based on level (pigz/gzip convention) */
static uint8_t gzip_xfl(int level) {
    if (level == 9 || level == 11) return 2;
    if (level == 1) return 4;
    return 0;
}

/* Write a gzip header. If name is non-null, include it. Returns 0 or -1. */
static int write_gzip_header(int fd, int level, uint32_t mtime, const char *name, const char *comment) {
    uint8_t hdr[10];
    uint8_t flags = 0;
    if (name) flags |= 0x08;
    if (comment) flags |= 0x10;
    hdr[0] = 0x1f;
    hdr[1] = 0x8b;
    hdr[2] = 8;
    hdr[3] = flags;
    put_u32(hdr + 4, mtime);
    hdr[8] = gzip_xfl(level);
    hdr[9] = 3; /* UNIX */
    if (write_all(fd, hdr, 10)) return -1;
    if (name) {
        size_t n = strlen(name) + 1;
        if (write_all(fd, name, n)) return -1;
    }
    if (comment) {
        size_t n = strlen(comment) + 1;
        if (write_all(fd, comment, n)) return -1;
    }
    return 0;
}

static int write_gzip_trailer(int fd, uint32_t crc, uint32_t total) {
    uint8_t tr[8];
    put_u32(tr, crc);
    put_u32(tr + 4, total);
    return write_all(fd, tr, 8);
