static int write_zlib_header(int fd, int level) {
    uint8_t h[2];
    unsigned int cm = 8;        /* deflate */
    unsigned int cinfo = 7;     /* 32K window */
    h[0] = (uint8_t)((cinfo << 4) | cm);
    unsigned int flevel;
    if (level <= 1) flevel = 0;
    else if (level < 6) flevel = 1;
    else if (level == 6) flevel = 2;
    else flevel = 3;
    unsigned int cmf = h[0];
    unsigned int flg = (flevel << 6);
    unsigned int tmp = (cmf << 8) | flg;
    unsigned int rem = tmp % 31;
    flg += (31 - rem);
    h[1] = (uint8_t)flg;
    return write_all(fd, h, 2);
}

static int write_zlib_trailer(int fd, uint32_t adler) {
    uint8_t tr[4];
    /* zlib adler is big-endian */
    tr[0] = (adler >> 24) & 0xff;
    tr[1] = (adler >> 16) & 0xff;
    tr[2] = (adler >> 8) & 0xff;
    tr[3] = adler & 0xff;
    return write_all(fd, tr, 4);
}

/* DOS date/time conversion */
static void dos_time(time_t t, uint16_t *dosdate, uint16_t *dostime) {
    struct tm *tm = localtime(&t);
    struct tm fallback;
    if (!tm) { memset(&fallback, 0, sizeof(fallback)); fallback.tm_year = 80; tm = &fallback; }
    int y = tm->tm_year + 1900 - 1980;
    if (y < 0) y = 0;
    if (y > 127) y = 127;
    *dosdate = (uint16_t)((y << 9) | ((tm->tm_mon + 1) << 5) | tm->tm_mday);
    *dostime = (uint16_t)((tm->tm_hour << 11) | (tm->tm_min << 5) | (tm->tm_sec / 2));
