/* Compress from input fd to output fd using raw deflate.
 * Returns 0 on success. Populates crc and adler and totals via pointers. */
static int deflate_stream(int infd, int outfd, int level, int strategy,
                          int wrap, /* 0=raw, 15=zlib, 31=gzip (we use raw) */
                          uint32_t *out_crc, uint32_t *out_adler,
                          uint64_t *out_in, uint64_t *out_out) {
    z_stream zs;
    memset(&zs, 0, sizeof(zs));
    int windowBits = (wrap == 0) ? -15 : wrap;
    int memLevel = 8;
    int rv = deflateInit2(&zs, level, Z_DEFLATED, windowBits, memLevel, strategy);
    if (rv != Z_OK) return -1;

    const size_t BUFSZ = 131072;
    uint8_t *in = (uint8_t*)malloc(BUFSZ);
    uint8_t *out = (uint8_t*)malloc(BUFSZ);
    if (!in || !out) { free(in); free(out); deflateEnd(&zs); return -1; }

    uint32_t crc = crc32(0L, Z_NULL, 0);
    uint32_t adl = adler32(0L, Z_NULL, 0);
    uint64_t total_in = 0, total_out = 0;

    int flush = Z_NO_FLUSH;
    for (;;) {
        int r = read_all(infd, in, BUFSZ);
        if (r < 0) { free(in); free(out); deflateEnd(&zs); return -1; }
        if (r == 0) flush = Z_FINISH;
        total_in += (uint64_t)r;
        crc = crc32(crc, in, (unsigned)r);
        adl = adler32(adl, in, (unsigned)r);
        zs.next_in = in;
        zs.avail_in = (uInt)r;
        do {
            zs.next_out = out;
            zs.avail_out = (uInt)BUFSZ;
            rv = deflate(&zs, flush);
            if (rv == Z_STREAM_ERROR) { free(in); free(out); deflateEnd(&zs); return -1; }
            size_t have = BUFSZ - zs.avail_out;
            if (have > 0) {
                if (write_all(outfd, out, have)) { free(in); free(out); deflateEnd(&zs); return -1; }
                total_out += (uint64_t)have;
            }
        } while (zs.avail_out == 0);
        if (flush == Z_FINISH) break;
    }
    deflateEnd(&zs);
    free(in); free(out);
    if (out_crc) *out_crc = crc;
    if (out_adler) *out_adler = adl;
    if (out_in) *out_in = total_in;
    if (out_out) *out_out = total_out;
    return 0;
}

