            if (rv == Z_NEED_DICT || rv == Z_DATA_ERROR || rv == Z_MEM_ERROR) {
                free(in); free(out); inflateEnd(&zs); return -1;
            }
            size_t have = BUFSZ - zs.avail_out;
            if (have > 0) {
                crc = crc32(crc, out, (unsigned)have);
                adl = adler32(adl, out, (unsigned)have);
                tout += (uint64_t)have;
                if (write_output) {
                    if (write_all(outfd, out, have)) {
                        free(in); free(out); inflateEnd(&zs); return -1;
                    }
                }
            }
        } while (zs.avail_out == 0 && rv != Z_STREAM_END);
        /* tin is just the total bytes consumed by inflate */
        tin = zs.total_in;
        if (rv == Z_STREAM_END) {
            /* Remaining bytes in `in` that are past the stream end: push to tail */
            int leftover = (int)zs.avail_in;
            if (tail && leftover > 0) {
                memcpy(tail, zs.next_in, leftover);
                *taill = leftover;
            }
            avail = 0;
            done = 1;
        } else {
            avail = 0;
        }
    }
    inflateEnd(&zs);
    free(in); free(out);
    if (crc_out) *crc_out = crc;
    if (adler_out) *adler_out = adl;
    if (total_in_out) *total_in_out = tin;
    if (total_out_out) *total_out_out = tout;
    return 0;
