/* Read enough bytes to detect format. Returns format (0 gzip, 1 zlib, 2 zip, -1 unknown) */
static int detect_format(const uint8_t *buf, int n) {
    if (n >= 2 && buf[0] == 0x1f && buf[1] == 0x8b) return 0;
    if (n >= 4 && buf[0] == 'P' && buf[1] == 'K' && buf[2] == 3 && buf[3] == 4) return 2;
    /* zlib: first byte CMF, second byte FLG. (CMF*256 + FLG) % 31 == 0, CM==8 */
    if (n >= 2 && (buf[0] & 0x0f) == 8 && (((unsigned)buf[0] << 8) | buf[1]) % 31 == 0) return 1;
    return -1;
}

/* Skip a local file header of a zip entry and position just before the data.
 * Populate name (malloc'd), mtime, method. Returns compressed size if known, else -1. */
struct zip_local {
    char *name;
    uint32_t mtime;
    uint32_t crc;
    uint32_t csize;
    uint32_t usize;
    int method;
    int has_data_descr;
};

static int read_zip_local(int fd, const uint8_t *first4, struct zip_local *z) {
    uint8_t h[26]; /* after sig */
    memcpy(h, first4, 4); /* we won't re-read sig */
    if (read_all(fd, h, 26) != 26) return -1;
    int method = get_u16(h + 4);
    int gpf = get_u16(h + 2);
    uint32_t dostime = get_u16(h + 6);
    uint32_t dosdate = get_u16(h + 8);
    (void)dostime; (void)dosdate;
    uint32_t crc = get_u32(h + 10);
    uint32_t csize = get_u32(h + 14);
    uint32_t usize = get_u32(h + 18);
    int namelen = get_u16(h + 22);
    int extralen = get_u16(h + 24);
    char *name = (char*)malloc(namelen + 1);
    if (!name) return -1;
    if (read_all(fd, name, namelen) != namelen) { free(name); return -1; }
    name[namelen] = 0;
    if (extralen) {
        uint8_t *x = (uint8_t*)malloc(extralen);
        if (!x) { free(name); return -1; }
        if (read_all(fd, x, extralen) != extralen) { free(x); free(name); return -1; }
        free(x);
    }
    z->name = name;
    z->mtime = 0; /* we don't parse DOS time */
    z->crc = crc;
    z->csize = csize;
    z->usize = usize;
    z->method = method;
    z->has_data_descr = (gpf & 0x08) ? 1 : 0;
    return 0;
}

