/* -------- File processing -------- */

static int has_suffix(const char *s, const char *suf) {
    size_t sl = strlen(s), fl = strlen(suf);
    if (fl > sl) return 0;
    return strcmp(s + sl - fl, suf) == 0;
}

/* Strip a suffix if present. Returns malloc'd string. */
static char *strip_suffix(const char *name) {
    const char *suffixes[] = { ".gz", ".z", ".Z", ".zz", ".zip", "-gz", "-z", "_z", ".tgz", ".taz", NULL };
    size_t nl = strlen(name);
    for (int i = 0; suffixes[i]; i++) {
        size_t sl = strlen(suffixes[i]);
        if (nl > sl && strcmp(name + nl - sl, suffixes[i]) == 0) {
            char *out;
            if (strcmp(suffixes[i], ".tgz") == 0 || strcmp(suffixes[i], ".taz") == 0) {
                out = (char*)malloc(nl - sl + 5);
                memcpy(out, name, nl - sl);
                strcpy(out + (nl - sl), ".tar");
                return out;
            }
            out = (char*)malloc(nl - sl + 1);
            memcpy(out, name, nl - sl);
            out[nl - sl] = 0;
            return out;
        }
    }
    /* custom suffix */
    if (g_suffix && strcmp(g_suffix, ".gz") != 0) {
        size_t sl = strlen(g_suffix);
        if (nl > sl && strcmp(name + nl - sl, g_suffix) == 0) {
            char *out = (char*)malloc(nl - sl + 1);
            memcpy(out, name, nl - sl);
            out[nl - sl] = 0;
            return out;
        }
    }
    return NULL;
}

static int is_terminal(int fd) {
    return isatty(fd);
}

/* basename without directory */
static const char *basename_ptr(const char *path) {
    const char *p = strrchr(path, '/');
    return p ? p + 1 : path;
}

/* Compress a single file.
 * If inpath is NULL, compress from stdin to stdout.
 * Otherwise compress inpath -> outpath (or stdout if g_stdout). */
static int compress_one(const char *inpath) {
    int infd;
    const char *display_in;
    char *outpath = NULL;
    const char *display_out = NULL;
    struct stat st; int have_st = 0;
    uint32_t mtime = 0;
    const char *hdrname = NULL;

    if (inpath == NULL || strcmp(inpath, "-") == 0) {
        infd = 0;
        display_in = "<stdin>";
    } else {
        if (stat(inpath, &st) != 0) {
            pigz_skip("%s does not exist", inpath);
            return -1;
        }
        have_st = 1;
        if (S_ISDIR(st.st_mode)) {
            if (!g_recursive) {
                pigz_skip("%s is a directory -- ignored", inpath);
                return -1;
            }
            /* recursive handling is elsewhere */
            return 0;
        }
        if (!S_ISREG(st.st_mode) && !g_force) {
            pigz_skip("%s is not a regular file", inpath);
            return -1;
        }
        /* check if already has compression suffix */
        if (!g_force && !g_stdout) {
            const char *known_sufs[] = {".gz",".z",".Z",".zz",".zip",".tgz",".taz",NULL};
            for (int i = 0; known_sufs[i]; i++) {
                if (has_suffix(inpath, known_sufs[i])) {
                    pigz_skip("%s ends with %s", inpath, known_sufs[i]);
                    return -1;
                }
            }
        }
        infd = open(inpath, O_RDONLY);
        if (infd < 0) {
            pigz_skip("%s does not exist", inpath);
            return -1;
        }
        display_in = inpath;
        mtime = (uint32_t)st.st_mtime;
    }

    int outfd;
    if (g_stdout) {
        outfd = 1;
        display_out = "<stdout>";
    } else if (inpath == NULL || strcmp(inpath, "-") == 0) {
        outfd = 1;
        display_out = "<stdout>";
    } else {
        const char *suf = g_format == 1 ? ".zz" : (g_format == 2 ? ".zip" : g_suffix);
        size_t n = strlen(inpath) + strlen(suf) + 1;
        outpath = (char*)malloc(n);
        snprintf(outpath, n, "%s%s", inpath, suf);
        if (!g_force) {
            if (access(outpath, F_OK) == 0) {
                pigz_skip("%s exists", outpath);
                free(outpath);
                close(infd);
                return -1;
            }
        }
        outfd = open(outpath, O_WRONLY | O_CREAT | O_TRUNC, have_st ? (st.st_mode & 0777) : 0644);
        if (outfd < 0) {
            pigz_skip("%s (%s)", outpath, strerror(errno));
            free(outpath);
            close(infd);
            return -1;
        }
        display_out = outpath;
    }

    /* Check terminal output */
    if (outfd == 1 && !g_force && is_terminal(1)) {
        pigz_die("trying to write compressed data to a terminal (use -f to force)");
    }

    /* Determine header name/mtime */
    int use_name = g_headname;
    int use_time = g_headtime;
    if (use_name < 0) use_name = (inpath != NULL && strcmp(inpath, "-") != 0) ? 1 : 0;
    if (use_time < 0) use_time = (inpath != NULL && strcmp(inpath, "-") != 0) ? 1 : 0;
    const char *bn = (inpath && strcmp(inpath, "-") != 0) ? basename_ptr(inpath) : NULL;
    hdrname = use_name ? bn : NULL;
    uint32_t header_mtime = use_time ? mtime : 0;

    uint32_t crc = 0, adl = 0;
    uint64_t total_in = 0, total_out = 0;

    int use_level = g_level == 11 ? 9 : g_level;
    int use_strategy = g_strategy;

    if (g_format == 0) {
        /* gzip */
        if (write_gzip_header(outfd, g_level, header_mtime, hdrname, g_comment)) goto werror;
        if (deflate_stream(infd, outfd, use_level, use_strategy, 0, &crc, &adl, &total_in, &total_out)) goto cerror;
        if (write_gzip_trailer(outfd, crc, (uint32_t)total_in)) goto werror;
    } else if (g_format == 1) {
        /* zlib */
        if (write_zlib_header(outfd, g_level)) goto werror;
        if (deflate_stream(infd, outfd, use_level, use_strategy, 0, &crc, &adl, &total_in, &total_out)) goto cerror;
        if (write_zlib_trailer(outfd, adl)) goto werror;
    } else {
        /* zip single entry */
        /* Local file header */
        const char *zname = hdrname ? hdrname : (inpath && strcmp(inpath,"-") != 0 ? basename_ptr(inpath) : g_alias);
        if (!zname) zname = "-";
        size_t namelen = strlen(zname);
        uint16_t dosdate = 0, dostime = 0;
        if (header_mtime) dos_time((time_t)header_mtime, &dosdate, &dostime);
        /* Write local file header with unknown sizes (bit 3 set) */
        uint8_t lh[30];
        memset(lh, 0, sizeof(lh));
        put_u32(lh, 0x04034b50);
        put_u16(lh + 4, 45);     /* version needed */
        put_u16(lh + 6, 0x08);   /* general purpose bit flag: data descriptor */
        put_u16(lh + 8, 8);      /* deflate */
        put_u16(lh + 10, dostime);
        put_u16(lh + 12, dosdate);
        put_u32(lh + 14, 0);     /* crc32 - in data descriptor */
        put_u32(lh + 18, 0);     /* csize */
        put_u32(lh + 22, 0);     /* usize */
        put_u16(lh + 26, (uint16_t)namelen);
        put_u16(lh + 28, 0);     /* extra len */
        if (write_all(outfd, lh, 30)) goto werror;
        if (write_all(outfd, zname, namelen)) goto werror;
        uint64_t data_start = 30 + namelen;
        (void)data_start;
        if (deflate_stream(infd, outfd, use_level, use_strategy, 0, &crc, &adl, &total_in, &total_out)) goto cerror;
        /* Data descriptor */
        uint8_t dd[16];
        put_u32(dd, 0x08074b50);
        put_u32(dd + 4, crc);
        put_u32(dd + 8, (uint32_t)total_out);
        put_u32(dd + 12, (uint32_t)total_in);
        if (write_all(outfd, dd, 16)) goto werror;
        /* Central directory */
        uint8_t cd[46];
        memset(cd, 0, sizeof(cd));
        put_u32(cd, 0x02014b50);
        put_u16(cd + 4, 45);
        put_u16(cd + 6, 45);
        put_u16(cd + 8, 0x08);
        put_u16(cd + 10, 8);
        put_u16(cd + 12, dostime);
        put_u16(cd + 14, dosdate);
        put_u32(cd + 16, crc);
        put_u32(cd + 20, (uint32_t)total_out);
        put_u32(cd + 24, (uint32_t)total_in);
        put_u16(cd + 28, (uint16_t)namelen);
        put_u16(cd + 30, 0);
        put_u16(cd + 32, g_comment ? (uint16_t)strlen(g_comment) : 0);
        put_u16(cd + 34, 0);
        put_u16(cd + 36, 0);
        put_u32(cd + 38, 0);
        put_u32(cd + 42, 0);
        if (write_all(outfd, cd, 46)) goto werror;
        if (write_all(outfd, zname, namelen)) goto werror;
        if (g_comment && write_all(outfd, g_comment, strlen(g_comment))) goto werror;
        /* EOCD */
        uint64_t cd_size = 46 + namelen + (g_comment ? strlen(g_comment) : 0);
        uint64_t cd_off = data_start + total_out + 16;
        uint8_t eo[22];
        memset(eo, 0, sizeof(eo));
        put_u32(eo, 0x06054b50);
        put_u16(eo + 4, 0);
        put_u16(eo + 6, 0);
        put_u16(eo + 8, 1);
        put_u16(eo + 10, 1);
        put_u32(eo + 12, (uint32_t)cd_size);
        put_u32(eo + 16, (uint32_t)cd_off);
        put_u16(eo + 20, 0);
        if (write_all(outfd, eo, 22)) goto werror;
    }

    if (g_synchronous && outfd != 1) fsync(outfd);

    if (g_verbose && !g_quiet) {
        fprintf(stderr, "%s to %s \n", display_in, display_out);
    }

    if (infd != 0) close(infd);
    if (outfd != 1) {
        close(outfd);
        /* set times / permissions */
        if (have_st && outpath) {
            struct utimbuf ut;
            ut.actime = st.st_atime;
            ut.modtime = st.st_mtime;
            utime(outpath, &ut);
            chmod(outpath, st.st_mode & 0777);
        }
    }
    if (!g_keep && !g_stdout && inpath != NULL && strcmp(inpath, "-") != 0) {
        unlink(inpath);
    }
    free(outpath);
    return 0;

werror:
    pigz_skip("%s write error (%s)", display_out ? display_out : "<output>", strerror(errno));
    if (infd != 0) close(infd);
    if (outfd != 1) { close(outfd); if (outpath) unlink(outpath); }
    free(outpath);
    return -1;
cerror:
    pigz_skip("%s compression error", display_in);
    if (infd != 0) close(infd);
    if (outfd != 1) { close(outfd); if (outpath) unlink(outpath); }
    free(outpath);
    return -1;
