/* -------- Decompression of a single file -------- */

/* Decompress file at inpath (or stdin). mode: 1=decompress, 2=test, 3=list */
static int decompress_one(const char *inpath, int mode) {
    int infd;
    const char *display_in;
    struct stat st; int have_st = 0;
    if (inpath == NULL || strcmp(inpath, "-") == 0) {
        infd = 0;
        display_in = "<stdin>";
    } else {
        if (stat(inpath, &st) != 0) {
            pigz_skip("%s does not exist", inpath);
            return -1;
        }
        have_st = 1;
        if (S_ISDIR(st.st_mode)) {
            if (g_recursive) return 0;
            pigz_skip("%s is a directory -- ignored", inpath);
            return -1;
        }
        infd = open(inpath, O_RDONLY);
        if (infd < 0) {
            pigz_skip("%s does not exist", inpath);
            return -1;
        }
        display_in = inpath;
    }

    /* Read the first few bytes to detect format */
    uint8_t peek[32];
    int peekn = read_all(infd, peek, sizeof(peek));
    if (peekn <= 0) {
        pigz_skip("%s empty", display_in);
        if (infd != 0) close(infd);
        return -1;
    }
    int fmt = detect_format(peek, peekn);
    if (fmt < 0) {
        pigz_skip("%s unrecognized format", display_in);
        if (infd != 0) close(infd);
        return -1;
    }

    /* Determine output path */
    int outfd = -1;
    char *outpath = NULL;
    const char *display_out = NULL;
    char *stored_name = NULL;
    uint32_t header_mtime = 0;

    if (mode == 1) {
        if (g_stdout || inpath == NULL || strcmp(inpath, "-") == 0) {
            outfd = 1;
            display_out = "<stdout>";
        }
        /* else defer opening until we know the output filename */
    } else {
        outfd = -1;
    }

    /* Process first member */
    int rv = 0;
    uint32_t total_crc = 0;
    uint64_t total_uncomp = 0;
    uint64_t total_comp = 0;
    uint32_t last_check = 0;
    int member_count = 0;
    int method = 0;

    /* Determine output for file mode */
    if (mode == 1 && outfd == -1) {
        /* open based on stored name or stripped name */
        char *out;
        if (g_headname == 1 && fmt == 0) {
            /* we might want stored name - read header first */
            /* We'll set it after reading header (see below). */
            out = NULL;
        } else {
            out = strip_suffix(inpath);
            if (!out) {
                pigz_skip("%s unknown suffix -- ignored", inpath);
                close(infd);
                return -1;
            }
        }
        if (out) {
            outpath = out;
            if (!g_force) {
                if (access(outpath, F_OK) == 0) {
                    pigz_skip("%s exists", outpath);
                    close(infd);
                    free(outpath);
                    return -1;
                }
            }
            outfd = open(outpath, O_WRONLY | O_CREAT | O_TRUNC, have_st ? (st.st_mode & 0777) : 0644);
            if (outfd < 0) {
                pigz_skip("%s (%s)", outpath, strerror(errno));
                close(infd);
                free(outpath);
                return -1;
            }
            display_out = outpath;
        }
    }

    int leadn = peekn;
    uint8_t leadbuf[32];
    memcpy(leadbuf, peek, peekn);

    for (;;) {
        if (fmt == 0) {
            /* gzip */
            struct gz_hdr_info h; memset(&h, 0, sizeof(h));
            int rr = read_gzip_header(infd, &h, leadbuf, &leadn);
            if (rr == 1) break; /* eof cleanly between members */
            if (rr < 0) {
                if (member_count == 0) {
                    pigz_skip("%s unrecognized format", display_in);
                } else {
                    /* Trailing garbage: just stop */
                }
                rv = -1;
                break;
            }
            method = h.method;
            if (h.method != 8) {
                pigz_skip("%s compression method not supported", display_in);
                free(h.name); free(h.comment);
                rv = -1; break;
            }
            if (member_count == 0) {
                header_mtime = h.mtime;
                if (h.name) stored_name = strdup(h.name);
            }
            free(h.name); free(h.comment);

            /* If we needed to defer output path to stored name */
            if (mode == 1 && outfd == -1 && member_count == 0) {
                char *out;
                if (g_headname == 1 && stored_name && *stored_name) {
                    /* use basename part only */
                    const char *bn = basename_ptr(stored_name);
                    out = strdup(bn);
                } else {
                    out = strip_suffix(inpath);
                }
                if (!out) {
                    pigz_skip("%s unknown suffix -- ignored", inpath);
                    rv = -1; break;
                }
                outpath = out;
                if (!g_force && access(outpath, F_OK) == 0) {
                    pigz_skip("%s exists", outpath);
                    rv = -1; break;
                }
                outfd = open(outpath, O_WRONLY | O_CREAT | O_TRUNC, have_st ? (st.st_mode & 0777) : 0644);
                if (outfd < 0) {
                    pigz_skip("%s (%s)", outpath, strerror(errno));
                    rv = -1; break;
                }
                display_out = outpath;
            }

            uint32_t crc, adl;
            uint64_t tin, tout;
            if (inflate_raw(infd, mode == 1 ? outfd : -1, &crc, &adl, &tin, &tout,
                            leadbuf, &leadn, -1, mode == 1)) {
                pigz_skip("%s corrupted input -- invalid deflate data", display_in);
                rv = -1; break;
            }
            /* Read 8-byte trailer (CRC32 + ISIZE) */
            uint8_t tr[8];
            int ntr = 0;
            if (leadn > 0) {
                int take = leadn < 8 ? leadn : 8;
                memcpy(tr, leadbuf, take);
                ntr = take;
                if (take < leadn) {
                    memmove(leadbuf, leadbuf + take, leadn - take);
                    leadn -= take;
                } else {
                    leadn = 0;
                }
            }
            if (ntr < 8) {
                if (read_all(infd, tr + ntr, 8 - ntr) != 8 - ntr) {
                    pigz_skip("%s corrupted input -- missing trailer", display_in);
                    rv = -1; break;
                }
            }
            uint32_t expected_crc = get_u32(tr);
            uint32_t expected_len = get_u32(tr + 4);
            if (expected_crc != crc || expected_len != (uint32_t)tin) {
                pigz_skip("%s corrupted -- crc32 mismatch", display_in);
                rv = -1; break;
            }
            total_uncomp += tin;
            last_check = crc;
            total_crc = crc;
            total_comp += tout;
            member_count++;

            /* Check for another member */
            if (leadn == 0) {
                int r = read_all(infd, leadbuf, 2);
                if (r <= 0) break;
                leadn = r;
            }
            if (leadn < 2) {
                int r = read_all(infd, leadbuf + leadn, 2 - leadn);
                if (r <= 0) break;
                leadn += r;
            }
            if (leadbuf[0] != 0x1f || leadbuf[1] != 0x8b) break;
            /* continue loop */
        } else if (fmt == 1) {
            /* zlib: 2-byte header, already included in leadbuf. */
            /* Consume 2 header bytes from lead */
            if (leadn < 2) {
                int r = read_all(infd, leadbuf + leadn, 2 - leadn);
                if (r != 2 - leadn) { pigz_skip("%s corrupted", display_in); rv = -1; break; }
                leadn = 2;
            }
            memmove(leadbuf, leadbuf + 2, leadn - 2);
            leadn -= 2;
            method = 8;
            if (mode == 1 && outfd == -1) {
                char *out = strip_suffix(inpath);
                if (!out) {
                    pigz_skip("%s unknown suffix -- ignored", inpath);
                    rv = -1; break;
                }
                outpath = out;
                if (!g_force && access(outpath, F_OK) == 0) {
                    pigz_skip("%s exists", outpath);
                    rv = -1; break;
                }
                outfd = open(outpath, O_WRONLY | O_CREAT | O_TRUNC, have_st ? (st.st_mode & 0777) : 0644);
                if (outfd < 0) { pigz_skip("%s (%s)", outpath, strerror(errno)); rv = -1; break; }
                display_out = outpath;
            }
            uint32_t crc, adl; uint64_t tin, tout;
            if (inflate_raw(infd, mode == 1 ? outfd : -1, &crc, &adl, &tin, &tout,
                            leadbuf, &leadn, -1, mode == 1)) {
                pigz_skip("%s corrupted", display_in);
                rv = -1; break;
            }
            /* 4-byte adler32 trailer, big endian */
            uint8_t tr[4];
            int ntr = 0;
            if (leadn > 0) {
                int take = leadn < 4 ? leadn : 4;
                memcpy(tr, leadbuf, take);
                ntr = take;
                if (take < leadn) { memmove(leadbuf, leadbuf + take, leadn - take); leadn -= take; }
                else leadn = 0;
            }
            if (ntr < 4) {
                if (read_all(infd, tr + ntr, 4 - ntr) != 4 - ntr) { pigz_skip("%s corrupted", display_in); rv = -1; break; }
            }
            uint32_t expected = ((uint32_t)tr[0] << 24) | ((uint32_t)tr[1] << 16) | ((uint32_t)tr[2] << 8) | tr[3];
            if (expected != adl) { pigz_skip("%s corrupted", display_in); rv = -1; break; }
            total_uncomp += tin;
            last_check = adl;
            total_comp += tout;
            member_count++;
            break;
        } else if (fmt == 2) {
            /* zip */
            if (leadn < 4) { int r = read_all(infd, leadbuf + leadn, 4 - leadn); if (r <= 0) break; leadn += r; }
            struct zip_local z;
            memset(&z, 0, sizeof(z));
            /* consume 4 bytes sig from leadbuf */
            memmove(leadbuf, leadbuf + 4, leadn - 4); leadn -= 4;
            if (read_zip_local(infd, peek /* unused */, &z) != 0) {
                pigz_skip("%s corrupted zip", display_in);
                rv = -1; break;
            }
            method = z.method;
            if (mode == 1 && outfd == -1) {
                char *out;
                if (g_headname == 1 && z.name) {
                    const char *bn = basename_ptr(z.name);
                    out = strdup(bn);
                } else {
                    out = strip_suffix(inpath);
                    if (!out) out = strdup(z.name ? basename_ptr(z.name) : "out");
                }
                outpath = out;
                if (!g_force && access(outpath, F_OK) == 0) {
                    pigz_skip("%s exists", outpath);
                    free(z.name);
                    rv = -1; break;
                }
                outfd = open(outpath, O_WRONLY | O_CREAT | O_TRUNC, have_st ? (st.st_mode & 0777) : 0644);
                if (outfd < 0) { pigz_skip("%s (%s)", outpath, strerror(errno)); free(z.name); rv = -1; break; }
                display_out = outpath;
            }
            stored_name = z.name ? strdup(z.name) : NULL;
            uint32_t crc, adl; uint64_t tin, tout;
            if (z.method == 0) {
                /* stored */
                uint32_t remain = z.csize;
                uint8_t buf[65536];
                crc = crc32(0L, Z_NULL, 0);
                while (remain > 0) {
                    uint32_t want = remain > sizeof(buf) ? sizeof(buf) : remain;
                    int r = read_all(infd, buf, want);
                    if (r != (int)want) { pigz_skip("%s corrupted zip", display_in); rv = -1; break; }
                    crc = crc32(crc, buf, r);
                    if (mode == 1) write_all(outfd, buf, r);
                    remain -= r;
                }
                tin = z.usize; tout = z.csize; adl = 0;
            } else if (z.method == 8) {
                if (inflate_raw(infd, mode == 1 ? outfd : -1, &crc, &adl, &tin, &tout,
                                leadbuf, &leadn, -1, mode == 1)) {
                    pigz_skip("%s corrupted zip", display_in);
                    free(z.name); rv = -1; break;
                }
            } else {
                pigz_skip("%s zip method %d not supported", display_in, z.method);
                free(z.name); rv = -1; break;
            }
            if (z.has_data_descr) {
                /* Try to read 16-byte descriptor */
                uint8_t dd[16]; int ntr = 0;
                if (leadn > 0) { int take = leadn < 16 ? leadn : 16; memcpy(dd, leadbuf, take); ntr = take;
                                 memmove(leadbuf, leadbuf + take, leadn - take); leadn -= take; }
                if (ntr < 16) read_all(infd, dd + ntr, 16 - ntr);
                /* optionally verify */
            }
            total_uncomp += tin;
            last_check = crc;
            total_comp += tout;
            free(z.name);
            member_count++;
            break;
        }
    }

    if (rv != 0) {
        if (outpath && outfd != 1 && outfd >= 0) { close(outfd); unlink(outpath); }
        free(outpath); free(stored_name);
        if (infd != 0) close(infd);
        return -1;
    }

    if (mode == 3) {
        /* list */
        if (!g_quiet) {
            const char *method_name = (fmt == 0 ? "gzip" : (fmt == 1 ? "zlib" : "zip "));
            static int header_printed = 0;
            if (g_verbose) {
                if (!header_printed) {
                    printf("method    check    timestamp    compressed   original reduced  name\n");
                    header_printed = 1;
                }
                char tsbuf[32];
                if (fmt == 0 && header_mtime != 0) {
