/* -------- recursive walk -------- */

static void process_entry(const char *path);

static void process_dir(const char *path) {
    DIR *d = opendir(path);
    if (!d) { pigz_skip("%s (%s)", path, strerror(errno)); return; }
    struct dirent *e;
    while ((e = readdir(d)) != NULL) {
        if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0) continue;
        size_t n = strlen(path) + 1 + strlen(e->d_name) + 1;
        char *np = (char*)malloc(n);
        snprintf(np, n, "%s/%s", path, e->d_name);
        process_entry(np);
        free(np);
    }
    closedir(d);
}

static void process_entry(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) {
        pigz_skip("%s does not exist", path);
        return;
    }
    if (S_ISDIR(st.st_mode)) {
        if (g_recursive) process_dir(path);
        else pigz_skip("%s is a directory -- ignored", path);
        return;
    }
    if (g_decode == 0) compress_one(path);
    else decompress_one(path, g_decode);
}

/* -------- main -------- */

int main(int argc, char **argv) {
    /* Determine program name */
    g_prog = basename_ptr(argv[0]);

    /* Defaults from program name */
    const char *pn = g_prog;
    if (strstr(pn, "unpigz") || strstr(pn, "gunzip")) {
        g_decode = 1;
    } else if (strstr(pn, "gzcat") || strstr(pn, "zcat")) {
        g_decode = 1;
        g_stdout = 1;
    }

    /* Merge args with env vars */
    argv_t all;
    argv_init(&all);
    const char *gz = getenv("GZIP");
    if (gz) argv_split(&all, gz);
    const char *pz = getenv("PIGZ");
    if (pz) argv_split(&all, pz);
    for (int i = 1; i < argc; i++) argv_push(&all, argv[i]);

    argv_t files;
    argv_init(&files);
    parse_options(all.n, all.v, &files);

    if (files.n == 0) {
        /* stdin */
        if (g_decode == 0) {
            compress_one(NULL);
        } else {
            decompress_one(NULL, g_decode == 2 ? 2 : (g_decode == 3 ? 3 : 1));
        }
    } else {
        for (int i = 0; i < files.n; i++) {
            const char *p = files.v[i];
            if (strcmp(p, "-") == 0) {
                if (g_decode == 0) compress_one(NULL);
                else decompress_one(NULL, g_decode);
            } else {
                process_entry(p);
            }
        }
    }

    return g_exit;
}

