/* -------- Decompression (buffered) -------- */

typedef struct {
    int fd;
    uint8_t *buf;
    size_t cap;
    size_t pos;
    size_t len;
    int eof;
} bufio_t;

static void bufio_init(bufio_t *b, int fd) {
    b->fd = fd;
    b->cap = 131072;
    b->buf = (uint8_t*)malloc(b->cap);
    b->pos = 0;
    b->len = 0;
    b->eof = 0;
}

static void bufio_free(bufio_t *b) {
    free(b->buf);
    b->buf = NULL;
}

/* Ensure at least one byte available; return 1 if data available, 0 at eof, -1 on error */
static int bufio_ensure(bufio_t *b) {
    if (b->pos < b->len) return 1;
    if (b->eof) return 0;
    b->pos = 0;
    ssize_t r = read(b->fd, b->buf, b->cap);
    if (r < 0) return -1;
    if (r == 0) { b->eof = 1; b->len = 0; return 0; }
    b->len = (size_t)r;
    return 1;
}

/* Read exactly n bytes; return number of bytes read (may be less at EOF). */
static int bufio_read(bufio_t *b, void *out, size_t n) {
    size_t got = 0;
    uint8_t *p = (uint8_t*)out;
    while (got < n) {
        int r = bufio_ensure(b);
        if (r <= 0) return (int)got;
        size_t take = b->len - b->pos;
        if (take > n - got) take = n - got;
        memcpy(p + got, b->buf + b->pos, take);
        b->pos += take;
        got += take;
    }
    return (int)got;
}

/* Peek at buffer (returns pointer into buf, with at least 'want' bytes, or less at EOF) */
/* Returns actual number of bytes available in the contiguous peek region. */
static int bufio_peek(bufio_t *b, int want, const uint8_t **pp) {
    while ((int)(b->len - b->pos) < want && !b->eof) {
        /* move data to start */
        if (b->pos > 0) {
            memmove(b->buf, b->buf + b->pos, b->len - b->pos);
            b->len -= b->pos; b->pos = 0;
        }
        if (b->len >= b->cap) break;
        ssize_t r = read(b->fd, b->buf + b->len, b->cap - b->len);
        if (r < 0) return -1;
        if (r == 0) { b->eof = 1; break; }
        b->len += (size_t)r;
    }
    *pp = b->buf + b->pos;
    return (int)(b->len - b->pos);
}

/* consume n bytes from buffer */
static void bufio_consume(bufio_t *b, int n) {
    b->pos += n;
}

/* Read C string (null terminated) */
static char *bufio_read_cstring(bufio_t *b) {
    size_t cap = 64, n = 0;
    char *s = (char*)malloc(cap);
    if (!s) return NULL;
    for (;;) {
        uint8_t c;
        if (bufio_read(b, &c, 1) != 1) { free(s); return NULL; }
        if (n + 1 >= cap) { cap *= 2; s = (char*)realloc(s, cap); if (!s) return NULL; }
        s[n++] = c;
        if (c == 0) break;
    }
    return s;
}

/* gzip header struct already defined earlier. We re-declare here in case. */
#ifndef GZ_HDR_INFO_DEFINED
#define GZ_HDR_INFO_DEFINED
#endif

/* Read gzip member header from buffer. Returns 1 if EOF (no member), 0 on success, -1 error */
struct gzh {
    int method;
    int flags;
    uint32_t mtime;
    int xfl;
    int os;
    char *name;
    char *comment;
};

static int read_gzip_header_bio(bufio_t *b, struct gzh *h) {
    uint8_t hdr[10];
    int r = bufio_read(b, hdr, 10);
    if (r == 0) return 1;
    if (r < 10) return -1;
    if (hdr[0] != 0x1f || hdr[1] != 0x8b) return -1;
    h->method = hdr[2];
    h->flags = hdr[3];
    h->mtime = get_u32(hdr + 4);
    h->xfl = hdr[8];
    h->os = hdr[9];
    h->name = NULL;
    h->comment = NULL;
