/* -------- Decompression (buffered) -------- */

typedef struct {
    int fd;
    uint8_t *buf;
    size_t cap;
    size_t pos;
    size_t len;
    int eof;
} bufio_t;

static void bufio_init(bufio_t *b, int fd) {
    b->fd = fd;
    b->cap = 131072;
    b->buf = (uint8_t*)malloc(b->cap);
    b->pos = 0;
    b->len = 0;
    b->eof = 0;
}

static void bufio_free(bufio_t *b) {
    free(b->buf);
    b->buf = NULL;
}

/* Ensure at least one byte available; return 1 if data available, 0 at eof, -1 on error */
static int bufio_ensure(bufio_t *b) {
    if (b->pos < b->len) return 1;
    if (b->eof) return 0;
    b->pos = 0;
    ssize_t r = read(b->fd, b->buf, b->cap);
    if (r < 0) return -1;
    if (r == 0) { b->eof = 1; b->len = 0; return 0; }
    b->len = (size_t)r;
    return 1;
}

/* Read exactly n bytes; return number of bytes read (may be less at EOF). */
static int bufio_read(bufio_t *b, void *out, size_t n) {
    size_t got = 0;
    uint8_t *p = (uint8_t*)out;
    while (got < n) {
        int r = bufio_ensure(b);
        if (r <= 0) return (int)got;
        size_t take = b->len - b->pos;
        if (take > n - got) take = n - got;
        memcpy(p + got, b->buf + b->pos, take);
        b->pos += take;
        got += take;
    }
    return (int)got;
}

/* Peek at buffer (returns pointer into buf, with at least 'want' bytes, or less at EOF) */
/* Returns actual number of bytes available in the contiguous peek region. */
static int bufio_peek(bufio_t *b, int want, const uint8_t **pp) {
    while ((int)(b->len - b->pos) < want && !b->eof) {
        /* move data to start */
        if (b->pos > 0) {
            memmove(b->buf, b->buf + b->pos, b->len - b->pos);
            b->len -= b->pos; b->pos = 0;
        }
        if (b->len >= b->cap) break;
        ssize_t r = read(b->fd, b->buf + b->len, b->cap - b->len);
        if (r < 0) return -1;
        if (r == 0) { b->eof = 1; break; }
        b->len += (size_t)r;
    }
    *pp = b->buf + b->pos;
    return (int)(b->len - b->pos);
}

/* consume n bytes from buffer */
static void bufio_consume(bufio_t *b, int n) {
    b->pos += n;
}

/* Read C string (null terminated) */
static char *bufio_read_cstring(bufio_t *b) {
    size_t cap = 64, n = 0;
    char *s = (char*)malloc(cap);
    if (!s) return NULL;
    for (;;) {
        uint8_t c;
        if (bufio_read(b, &c, 1) != 1) { free(s); return NULL; }
        if (n + 1 >= cap) { cap *= 2; s = (char*)realloc(s, cap); if (!s) return NULL; }
        s[n++] = c;
        if (c == 0) break;
    }
    return s;
}

/* gzip header struct already defined earlier. We re-declare here in case. */
#ifndef GZ_HDR_INFO_DEFINED
#define GZ_HDR_INFO_DEFINED
#endif

/* Read gzip member header from buffer. Returns 1 if EOF (no member), 0 on success, -1 error */
struct gzh {
    int method;
    int flags;
    uint32_t mtime;
    int xfl;
    int os;
    char *name;
    char *comment;
};

static int read_gzip_header_bio(bufio_t *b, struct gzh *h) {
    uint8_t hdr[10];
    int r = bufio_read(b, hdr, 10);
    if (r == 0) return 1;
    if (r < 10) return -1;
    if (hdr[0] != 0x1f || hdr[1] != 0x8b) return -1;
    h->method = hdr[2];
    h->flags = hdr[3];
    h->mtime = get_u32(hdr + 4);
    h->xfl = hdr[8];
    h->os = hdr[9];
    h->name = NULL;
    h->comment = NULL;
    if (h->flags & 0x04) {
        uint8_t len[2];
        if (bufio_read(b, len, 2) != 2) return -1;
        uint16_t n = get_u16(len);
        if (n > 0) {
            uint8_t *buf = (uint8_t*)malloc(n);
            if (!buf) return -1;
            if (bufio_read(b, buf, n) != n) { free(buf); return -1; }
            free(buf);
        }
    }
    if (h->flags & 0x08) { h->name = bufio_read_cstring(b); if (!h->name) return -1; }
    if (h->flags & 0x10) { h->comment = bufio_read_cstring(b); if (!h->comment) return -1; }
    if (h->flags & 0x02) {
        uint8_t c[2];
        if (bufio_read(b, c, 2) != 2) return -1;
    }
    return 0;
}

/* Inflate raw deflate from bufio to outfd. Returns 0 on success.
 * Fills *crc, *adler, *tin, *tout. If write_output==0, discards output. */
static int inflate_raw_bio(bufio_t *b, int outfd, int write_output,
                           uint32_t *crc_out, uint32_t *adler_out,
                           uint64_t *tin_out, uint64_t *tout_out) {
    z_stream zs; memset(&zs, 0, sizeof(zs));
    if (inflateInit2(&zs, -15) != Z_OK) return -1;
    const size_t BUFSZ = 131072;
    uint8_t *outbuf = (uint8_t*)malloc(BUFSZ);
    if (!outbuf) { inflateEnd(&zs); return -1; }
    uint32_t crc = crc32(0L, Z_NULL, 0);
    uint32_t adl = adler32(0L, Z_NULL, 0);
    uint64_t tin = 0, tout = 0;
    int rv = Z_OK;
    while (rv != Z_STREAM_END) {
        int r = bufio_ensure(b);
        if (r < 0) { free(outbuf); inflateEnd(&zs); return -1; }
        if (r == 0) { free(outbuf); inflateEnd(&zs); return -1; }
        zs.next_in = b->buf + b->pos;
        zs.avail_in = (uInt)(b->len - b->pos);
        uInt before_in = zs.avail_in;
        do {
            zs.next_out = outbuf;
            zs.avail_out = (uInt)BUFSZ;
            rv = inflate(&zs, Z_NO_FLUSH);
            if (rv == Z_NEED_DICT || rv == Z_DATA_ERROR || rv == Z_MEM_ERROR) {
                free(outbuf); inflateEnd(&zs); return -1;
            }
            size_t have = BUFSZ - zs.avail_out;
            if (have > 0) {
                crc = crc32(crc, outbuf, (unsigned)have);
                adl = adler32(adl, outbuf, (unsigned)have);
                tout += (uint64_t)have;
                if (write_output && outfd >= 0) {
                    if (write_all(outfd, outbuf, have)) {
                        free(outbuf); inflateEnd(&zs); return -1;
                    }
                }
            }
        } while (zs.avail_out == 0 && rv != Z_STREAM_END);
        uInt consumed = before_in - zs.avail_in;
        b->pos += consumed;
        tin += consumed;
    }
    free(outbuf);
    inflateEnd(&zs);
    if (crc_out) *crc_out = crc;
    if (adler_out) *adler_out = adl;
    if (tin_out) *tin_out = tin;
    if (tout_out) *tout_out = tout;
    return 0;
}

struct zip_loc {
    char *name;
    uint32_t crc, csize, usize;
    int method;
    int has_dd;
    uint16_t dostime, dosdate;
};

/* Read a zip local file header (sig already consumed) */
static int read_zip_local_bio(bufio_t *b, struct zip_loc *z) {
    uint8_t h[26];
    if (bufio_read(b, h, 26) != 26) return -1;
    int gpf = get_u16(h + 2);
    z->method = get_u16(h + 4);
    z->dostime = get_u16(h + 6);
    z->dosdate = get_u16(h + 8);
    z->crc = get_u32(h + 10);
    z->csize = get_u32(h + 14);
    z->usize = get_u32(h + 18);
    int namelen = get_u16(h + 22);
    int extralen = get_u16(h + 24);
    z->has_dd = (gpf & 0x08) ? 1 : 0;
    z->name = (char*)malloc(namelen + 1);
    if (!z->name) return -1;
    if (bufio_read(b, z->name, namelen) != namelen) return -1;
    z->name[namelen] = 0;
    if (extralen) {
        uint8_t *x = (uint8_t*)malloc(extralen);
        if (!x) return -1;
        if (bufio_read(b, x, extralen) != extralen) { free(x); return -1; }
        free(x);
    }
    return 0;
}

