static int detect_format_bytes(const uint8_t *buf, int n) {
    if (n >= 2 && buf[0] == 0x1f && buf[1] == 0x8b) return 0;
    if (n >= 4 && buf[0] == 'P' && buf[1] == 'K' && buf[2] == 3 && buf[3] == 4) return 2;
    if (n >= 2 && (buf[0] & 0x0f) == 8 && (((unsigned)buf[0] << 8) | buf[1]) % 31 == 0) return 1;
    return -1;
}

