        if (fmt == 0) {
            struct gzh h; memset(&h, 0, sizeof(h));
            int rr = read_gzip_header_bio(&bio, &h);
            if (rr == 1) break;
            if (rr < 0) {
                if (member_count == 0) pigz_skip("%s unrecognized format", display_in);
                rv = -1; break;
            }
            if (h.method != 8) {
                pigz_skip("%s compression method not supported", display_in);
                free(h.name); free(h.comment); rv = -1; break;
            }
            if (member_count == 0) {
                first_mtime = h.mtime;
                if (h.name) stored_name_first = strdup(h.name);
            }
            free(h.name); free(h.comment);

            if (mode == 1 && outfd < 0 && member_count == 0) {
                char *out;
                if (g_headname == 1 && stored_name_first && *stored_name_first) {
                    out = strdup(basename_ptr(stored_name_first));
                } else {
                    out = strip_suffix(inpath);
                }
                if (!out) {
                    pigz_skip("%s does not have a known suffix", inpath);
                    rv = -1; break;
                }
                outpath = out;
                if (!g_force && access(outpath, F_OK) == 0) {
                    pigz_skip("%s exists", outpath);
                    rv = -1; break;
                }
                outfd = open(outpath, O_WRONLY | O_CREAT | O_TRUNC, have_st ? (st.st_mode & 0777) : 0644);
                if (outfd < 0) { pigz_skip("%s (%s)", outpath, strerror(errno)); rv = -1; break; }
                display_out = outpath;
            }

