            if (inflate_raw_bio(&bio, mode == 1 ? outfd : -1, mode == 1, &crc, &adl, &tin, &tout)) {
                pigz_skip("%s corrupted input -- invalid deflate data", display_in);
                rv = -1; break;
            }
            uint8_t tr[8];
            if (bufio_read(&bio, tr, 8) != 8) { pigz_skip("%s corrupted input -- missing trailer", display_in); rv = -1; break; }
            uint32_t ec = get_u32(tr);
            uint32_t el = get_u32(tr + 4);
            if (ec != crc || el != (uint32_t)tin) {
                pigz_skip("%s corrupted -- crc32 mismatch", display_in);
                rv = -1; break;
            }
            total_uncomp += tin;
            total_comp += tout;
            last_check = crc;
            member_count++;

            /* Check for another member */
            const uint8_t *pp;
            int avail = bufio_peek(&bio, 2, &pp);
            if (avail < 2) break;
            if (pp[0] != 0x1f || pp[1] != 0x8b) break;
        } else if (fmt == 1) {
            /* zlib */
            uint8_t h[2];
            if (bufio_read(&bio, h, 2) != 2) { pigz_skip("%s corrupted", display_in); rv = -1; break; }

            if (mode == 1 && outfd < 0) {
                char *out = strip_suffix(inpath);
                if (!out) { pigz_skip("%s does not have a known suffix", inpath); rv = -1; break; }
                outpath = out;
                if (!g_force && access(outpath, F_OK) == 0) { pigz_skip("%s exists", outpath); rv = -1; break; }
                outfd = open(outpath, O_WRONLY | O_CREAT | O_TRUNC, have_st ? (st.st_mode & 0777) : 0644);
