                display_out = outpath;
            }
            uint32_t crc, adl; uint64_t tin, tout;
            if (inflate_raw_bio(&bio, mode == 1 ? outfd : -1, mode == 1, &crc, &adl, &tin, &tout)) {
                pigz_skip("%s corrupted", display_in); rv = -1; break;
            }
            uint8_t tr[4];
            if (bufio_read(&bio, tr, 4) != 4) { pigz_skip("%s corrupted", display_in); rv = -1; break; }
            uint32_t ec = ((uint32_t)tr[0] << 24) | ((uint32_t)tr[1] << 16) | ((uint32_t)tr[2] << 8) | tr[3];
            if (ec != adl) { pigz_skip("%s corrupted", display_in); rv = -1; break; }
            total_uncomp += tin;
            total_comp += tout + 2;
            last_check = adl;
            member_count++;
            break;
        } else { /* zip */
            uint8_t sig[4];
            if (bufio_read(&bio, sig, 4) != 4) { pigz_skip("%s corrupted zip", display_in); rv = -1; break; }
            struct zip_loc z; memset(&z, 0, sizeof(z));
            if (read_zip_local_bio(&bio, &z) != 0) { pigz_skip("%s corrupted zip", display_in); rv = -1; break; }

            if (mode == 1 && outfd < 0) {
                char *out;
                if (g_headname == 1 && z.name) out = strdup(basename_ptr(z.name));
                else {
                    out = strip_suffix(inpath);
                    if (!out) out = strdup(z.name ? basename_ptr(z.name) : "out");
                }
                outpath = out;
                if (!g_force && access(outpath, F_OK) == 0) { pigz_skip("%s exists", outpath); free(z.name); rv = -1; break; }
                outfd = open(outpath, O_WRONLY | O_CREAT | O_TRUNC, have_st ? (st.st_mode & 0777) : 0644);
                if (outfd < 0) { pigz_skip("%s (%s)", outpath, strerror(errno)); free(z.name); rv = -1; break; }
                display_out = outpath;
            }
            if (z.name) stored_name_first = strdup(z.name);
            uint32_t crc, adl; uint64_t tin, tout;
            if (z.method == 0) {
                uint32_t remain = z.csize;
                uint8_t buf[65536];
                crc = crc32(0L, Z_NULL, 0);
                while (remain > 0) {
                    uint32_t want = remain > sizeof(buf) ? sizeof(buf) : remain;
                    int r = bufio_read(&bio, buf, want);
                    if (r != (int)want) { pigz_skip("%s corrupted zip", display_in); rv = -1; break; }
                    crc = crc32(crc, buf, r);
                    if (mode == 1) write_all(outfd, buf, r);
                    remain -= r;
                }
                tin = z.usize; tout = z.csize;
            } else if (z.method == 8) {
                if (inflate_raw_bio(&bio, mode == 1 ? outfd : -1, mode == 1, &crc, &adl, &tin, &tout)) {
                    pigz_skip("%s corrupted zip", display_in); free(z.name); rv = -1; break;
                }
            } else {
                pigz_skip("%s zip method %d not supported", display_in, z.method);
                free(z.name); rv = -1; break;
            }
            if (z.has_dd) {
                uint8_t dd[16];
                bufio_read(&bio, dd, 16);
            }
            total_uncomp += tin;
            total_comp += tout;
            last_check = crc;
            free(z.name);
            member_count++;
            break;
        }
    }

    /* On success, print list info and verbose info */
    if (rv == 0 && mode == 3 && !g_quiet) {
        const char *dname;
        char *dnamebuf = NULL;
        if (inpath && strcmp(inpath, "-") != 0) {
            char *s = strip_suffix(inpath);
            if (s) { dnamebuf = s; dname = s; } else dname = inpath;
        } else {
            if (stored_name_first) dname = basename_ptr(stored_name_first);
            else dname = "<stdin>";
        }
        print_list_line(fmt, g_verbose, first_mtime, last_check,
                        total_comp, total_uncomp, member_count > 1, dname);
        free(dnamebuf);
    }

    if (rv == 0 && mode == 1 && g_verbose && !g_quiet) {
        fprintf(stderr, "%s to %s \n", display_in, display_out ? display_out : "<stdout>");
    }

    if (rv != 0) {
        if (outfd > 1) { close(outfd); if (outpath) unlink(outpath); }
        free(outpath); free(stored_name_first);
        bufio_free(&bio);
        if (infd != 0) close(infd);
        return -1;
    }

    bufio_free(&bio);
    if (infd != 0) close(infd);
    if (outfd > 1) {
        close(outfd);
        if (have_st && outpath) {
            struct utimbuf ut;
            if (first_mtime && g_headtime != 0) {
                ut.actime = st.st_atime;
                ut.modtime = (time_t)first_mtime;
            } else {
                ut.actime = st.st_atime;
                ut.modtime = st.st_mtime;
            }
            utime(outpath, &ut);
        }
    }
    if (!g_keep && mode == 1 && inpath && strcmp(inpath, "-") != 0 && !g_stdout && outpath) {
        unlink(inpath);
    }
    free(outpath); free(stored_name_first);
    return 0;
}

